function feedSelector(feed){return feed==='personal'?'#personalActivity':'#activityList'}
function nextFocusIndex(position,count){return count===0?-1:Math.min(position,count-1)}
function restoreFeedFocus(selector,position){const items=[...document.querySelectorAll(selector+' [data-del]')],at=nextFocusIndex(position,items.length),el=at>=0?items[at]:document.querySelector(selector==='#personalActivity'?'[data-panel="you"] [data-tab="record"]':'#syncStatus');if(el&&typeof el.focus==='function')el.focus()}
function feedFocusType(focused,active){return focused?active:null}
function requestDelete(index,id,feed){const item=state.logs[index];if(!item)return;const what=item.type==='bounty'?bountyTitle(item):`${CAT_LABELS[item.type]||item.type}${item.hardestGrade?' '+item.hardestGrade:''}`,buttons=[...document.querySelectorAll(feedSelector(feed)+' [data-del]')],position=Math.max(0,buttons.findIndex(el=>Number(el.dataset&&el.dataset.del)===index));state.pendingDelete={entry:item,index,id,feed,position,label:what};askConfirm('Delete this entry?',`Delete ${what} for ${item.name}?`,performDelete,'Delete',state.endpoint?'This cannot be undone.':'You can undo this from the bar that appears.')}
function resetFeedLimits(){state.crewFeedLimit=20;state.personalFeedLimit=5}
function filterByType(items,type){return !type||type==='all'?items:items.filter(x=>x&&x.type===type)}
function feedChips(){return[{type:'all',icon:'',label:'All'},...CATEGORIES.map(t=>({type:t,icon:TYPE_ICONS[t]||'',label:CAT_LABELS[t]||t}))]}
function renderFeedChips(sel,active){const el=document.querySelector(sel);if(!el)return;const focusType=feedFocusType(el===document.activeElement||(typeof el.contains==='function'&&el.contains(document.activeElement)),active);el.innerHTML=feedChips().map(c=>`<button class="cat-chip" type="button" data-feed-type="${c.type}" aria-pressed="${c.type===active}">${c.icon?`<b aria-hidden="true">${glyph(c.icon)}</b>`:''}${esc(c.label)}</button>`).join('');const chip=focusType&&typeof el.querySelector==='function'?el.querySelector('[data-feed-type="'+focusType+'"]'):null;if(chip&&typeof chip.focus==='function')chip.focus()}
function setFeedType(type,crew){const next=type&&CATEGORIES.includes(type)?type:'all';if(next===(crew?state.crewFeedType:state.feedType))return;if(crew)state.crewFeedType=next;else state.feedType=next;resetFeedLimits();render()}
function showMoreFeed(feed){if(feed==='personal')state.personalFeedLimit=Math.min(state.personalFeedLimit+5,state.logs.length);else state.crewFeedLimit=Math.min(state.crewFeedLimit+20,state.logs.length);render()}
function renderShowMore(id,shown,total){const btn=document.querySelector(id);if(!btn)return;btn.classList.toggle('hide',shown>=total)}
function undoDelete(){if(!state.lastDeleted||state.endpoint)return;const {entry,index}=state.lastDeleted;state.lastDeleted=null;state.logs=state.logs.slice(0,index).concat([entry],state.logs.slice(index));const stored=persistLocal();render();toast(stored?'Entry restored.':'Restored on this device only — storage is full.')}
function clearUndo(){state.lastDeleted=null;renderUndo()}
function renderUndo(){if(state.endpoint)state.lastDeleted=null;const bar=document.querySelector('#undoBar');if(!bar)return;const show=Boolean(state.lastDeleted);bar.classList.toggle('hide',!show);setText(document.querySelector('#undoText'),show?'Deleted '+state.lastDeleted.label+'.':'')}
async function performDelete(){const pending=state.pendingDelete;if(!pending)return;state.pendingDelete=null;const {entry,id,feed,position}=pending;if(state.endpoint){try{const response=await fetchShared(state.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'delete',id})}),result=await response.json();if(!response.ok||!result.ok)throw Error(result?.error?.message||'Delete rejected.');state.logs=state.logs.filter(x=>String(x.id)!==String(id));persistShared();render();loadRemote();toast('Entry deleted.')}catch(error){toast(`Delete failed — ${error.message}`)}}else{const at=state.logs.indexOf(entry);if(at>=0){state.lastDeleted={entry,index:at,label:pending.label||'entry'};state.logs=state.logs.filter(x=>x!==entry);persistLocal();render();toast('Entry deleted.')}}closeModal('confirmModal');restoreFeedFocus(feedSelector(feed),position)}
function addParticipantRow(person={name:''}){const el=document.querySelector('#participantRows'),index=el.children.length;el.insertAdjacentHTML('beforeend',`<div class="participant-row"><input aria-label="Participant ${index+1} name" class="participant-name" maxlength="30" placeholder="Name" value="${esc(person.name)}" /><button class="icon-btn remove-participant" type="button" aria-label="Remove ${esc(person.name||'participant')}">×</button></div>`)}
function populateSetup(){document.querySelector('#endpoint').value=state.endpoint;document.querySelector('#challengeStart').value=state.config.startDate;document.querySelector('#tripDate').value=state.config.tripDate;document.querySelector('#groupGoalInput').value=state.config.goal;const rows=document.querySelector('#participantRows');rows.innerHTML='';state.config.crew.forEach(addParticipantRow);if(!state.config.crew.length)addParticipantRow();document.querySelector('#scriptCode').textContent=SCRIPT}
function openSetup(){populateSetup();openModal('setupModal');document.querySelector('#endpoint').focus()}
function readSetupConfig(){const crew=[...document.querySelectorAll('.participant-row')].map(row=>({name:row.querySelector('.participant-name').value.trim()})).filter(x=>x.name);return{startDate:document.querySelector('#challengeStart').value,tripDate:document.querySelector('#tripDate').value,goal:Number(document.querySelector('#groupGoalInput').value),crew}}
function validateSetup(value){const parsed=parseRemoteConfig(value,[]),errors=Object.assign({},parsed.errors);if(!value.crew.length)errors.crew='Add at least one participant.';return{value:parsed.value,errors}}
async function testConnection(){const url=document.querySelector('#endpoint').value.trim(),result=document.querySelector('#testResult');result.textContent='Testing…';try{const response=await fetchShared(url),remote=unpackRemote(await response.json());result.textContent=`Connected — API v${remote.version}`;return true}catch(error){result.textContent=error.message==='version'?`Outdated Apps Script — deploy v${[...SUPPORTED_API_VERSIONS][0]}`:'Connection failed';return false}}
async function saveSetup(){const candidate=readSetupConfig(),check=validateSetup(candidate),errors=document.querySelector('#setupErrors'),url=document.querySelector('#endpoint').value.trim();if(Object.keys(check.errors).length){errors.textContent=Object.values(check.errors).join(' ');errors.classList.remove('hide');return}errors.classList.add('hide');const button=document.querySelector('#saveSetupBtn');button.disabled=true;button.textContent='Saving…';try{if(url){const response=await fetchShared(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'saveConfig',config:candidate})}),saved=await response.json();if(!response.ok||!saved.ok)throw Error(saved?.error?.message||'The Sheet rejected setup.');state.endpoint=url;writeStore('roadToSendEndpoint',state.endpoint);state.config=sanitizeConfig(saved.config,candidate);state.configErrors={};state.lastSyncedAt=Date.now();state.protocolVersion=[...SUPPORTED_API_VERSIONS][0];await loadRemote()}else{state.config=candidate;state.configErrors={};persistLocal();render()}closeModal('setupModal');const copied=await copyCrewLink();if(!participant(state.me))openIdentity(false);toast(url?(copied?'Shared setup saved. Crew link copied.':'Shared setup saved. Copy the crew link from setup.'):'Local setup saved.')}catch(error){errors.textContent=error.message||'Setup could not be saved.';errors.classList.remove('hide')}finally{button.disabled=false;button.textContent='Save centrally & copy crew link'}}
async function shareProgress(){const text=shareSummary(String(state.me).toLowerCase());if(!text)return false;const nav=typeof navigator==='undefined'?null:navigator;if(nav&&typeof nav.share==='function'){try{await nav.share({text});return true}catch(error){if(error&&error.name==='AbortError')return false}}return copyText(text,'Progress copied — paste it anywhere.')}
async function copyText(text,okMessage){try{const nav=typeof navigator==='undefined'?null:navigator;if(!nav||!nav.clipboard||!nav.clipboard.writeText)throw Error('no clipboard');await navigator.clipboard.writeText(String(text==null?'':text));toast(okMessage);return true}catch{toast('Copy failed — copy it manually.');return false}}
function publicUrl(){const url=new URL(location.href);url.hash='';url.searchParams.delete('sheet');return url.toString()}
function shareSummary(nameLower,today=challengeToday()){const key=String(nameLower==null?'':nameLower).trim().toLowerCase();if(!key)return'';const model=totalsModel(),i=model.sorted.findIndex(x=>x.name.toLowerCase()===key);if(i<0)return'';const row=model.sorted[i],prog=challengeProgress(today),lines=[`${row.name} · Road to Send`];if(prog)lines.push(`Day ${prog.day} of ${prog.totalDays}`);if(!row.total){lines.push('Just getting started — first points incoming.');lines.push(publicUrl());return lines.join('\n')}lines.push(`${row.total} pts · rank #${i+1}`);const spread=categoryBreakdown(key).rows.filter(r=>r.points>0).map(r=>`${r.label} ${r.points}`).join('  ');if(spread)lines.push(spread);const streak=streakInfo(key,today);lines.push(`${streak.current} day streak · best ${streak.best}`);const rec=personalRecords(key,today);if(rec.graded&&rec.hardest)lines.push(`Hardest send ${rec.hardest}`);lines.push(publicUrl());return lines.join('\n')}
async function copyCrewLink(){const url=new URL(publicUrl());if(state.endpoint)url.searchParams.set('sheet',state.endpoint);return copyText(url.toString(),'Crew link copied.')}
function copyScript(){copyText(SCRIPT,'Apps Script copied.')}
function exportData(){let url='';try{const blob=new Blob([JSON.stringify({version:[...SUPPORTED_API_VERSIONS][0],exportedAt:new Date().toISOString(),mode:state.endpoint?'shared-cache':'local',config:state.config,activities:state.logs},null,2)],{type:'application/json'}),a=document.createElement('a');url=URL.createObjectURL(blob);a.href=url;a.download=`road-to-send-${challengeToday()}.json`;a.click();toast('Export downloaded.')}catch{toast('Export failed — try a different browser.')}finally{if(url)URL.revokeObjectURL(url)}}
function disconnect(){askConfirm('Use local mode?','Switch this device to local mode? Shared Sheet data will remain untouched.',performDisconnect,'Use local mode','')}
function performDisconnect(){state.lastDeleted=null;resetFeedLimits();closeModal('confirmModal');localStorage.removeItem('roadToSendEndpoint');state.endpoint='';state.logs=sanitizeActivities(safeJson('roadToSendLogsV9',[],Array.isArray));state.config=sanitizeConfig(safeJson('roadToSendConfigV9',defaultConfig(),x=>x&&typeof x==='object'));state.syncState='local';state.configErrors={};closeModal('setupModal');setDefaultRecordDate();render();toast('Using local mode.')}
function init(){loadInitialState();document.querySelector('#hardestGrade').innerHTML='<option value="">Grade (optional)</option>'+GRADES.map(x=>`<option value="${x}">${x}</option>`).join('');setDefaultRecordDate();document.querySelectorAll('[data-tab]').forEach(x=>x.addEventListener('click',event=>{event.preventDefault();showTab(x.dataset.tab)}));document.querySelectorAll('input[name="activityType"]').forEach(x=>x.addEventListener('change',updateRecordPreview));document.querySelector('#hardestGrade').addEventListener('change',chooseGrade);const noteField=document.querySelector('#activityNote');if(noteField)noteField.addEventListener('input',updateRecordPreview);const bountySelect=document.querySelector('#bountySelect');if(bountySelect)bountySelect.addEventListener('change',updateRecordPreview);document.querySelector('#activityDate').addEventListener('change',updateRecordPreview);document.querySelector('#dateToggle').addEventListener('click',()=>{const box=document.querySelector('#dateFields'),toggle=document.querySelector('#dateToggle'),open=box.classList.toggle('hide')===false;toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'－ Use today instead':'＋ Different day';if(open)document.querySelector('#activityDate').focus();else{setDefaultRecordDate();updateRecordPreview()}});document.querySelector('#recordForm').addEventListener('submit',submitActivity);document.querySelector('#saveIdentity').addEventListener('click',saveIdentity);document.querySelector('#createProfile').addEventListener('click',createProfile);document.querySelector('#identityClose').addEventListener('click',()=>closeModal('identityModal'));const weekReviewClose=document.querySelector('#weekReviewClose');if(weekReviewClose)weekReviewClose.addEventListener('click',()=>closeModal('weekReviewModal'));const weekReviewCrewBtn=document.querySelector('#weekReviewCrewBtn');if(weekReviewCrewBtn)weekReviewCrewBtn.addEventListener('click',()=>{closeModal('weekReviewModal');showTab('crew')});document.querySelector('#saveProxy').addEventListener('click',saveProxy);const setLeaderMetric=v=>{if(state.leaderMetric===v)return;state.leaderMetric=v;render()},setLeaderScope=v=>{if(state.leaderScope===v)return;state.leaderScope=v;render()};document.querySelector('#leaderPointsBtn').addEventListener('click',()=>setLeaderMetric('points'));document.querySelector('#leaderBountyBtn').addEventListener('click',()=>setLeaderMetric('bounty'));document.querySelector('#leaderWeekBtn').addEventListener('click',()=>setLeaderScope('week'));document.querySelector('#leaderOverallBtn').addEventListener('click',()=>setLeaderScope('overall'));document.querySelector('#syncStatus').addEventListener('click',()=>loadRemote(true));document.querySelector('#diagnosticCode').addEventListener('click',()=>copyText(state.syncErrorCode,'Diagnostic code copied.'));const shareBtn=document.querySelector('#shareBtn');if(shareBtn)shareBtn.addEventListener('click',shareProgress);document.querySelector('#addParticipant').addEventListener('click',()=>addParticipantRow());document.querySelector('#participantRows').addEventListener('click',event=>{const button=event.target.closest('.remove-participant');if(button)button.closest('.participant-row').remove()});document.querySelector('#personalActivity').addEventListener('click',event=>{const button=event.target.closest('[data-del]');if(button)requestDelete(Number(button.dataset.del),button.dataset.id,'personal')});const feedFilter=document.querySelector('#feedFilter');if(feedFilter)feedFilter.addEventListener('click',event=>{const chip=event.target.closest('[data-feed-type]');if(chip)setFeedType(chip.dataset.feedType)});const crewFeedFilter=document.querySelector('#crewFeedFilter');if(crewFeedFilter)crewFeedFilter.addEventListener('click',event=>{const chip=event.target.closest('[data-feed-type]');if(chip)setFeedType(chip.dataset.feedType,true)});document.querySelector('#crew').addEventListener('click',event=>{const button=event.target.closest('[data-person]');if(button)openPersonCard(button.dataset.person)});document.querySelector('#personClose').addEventListener('click',()=>closeModal('personModal'));document.querySelector('#confirmOk').addEventListener('click',confirmProceed);document.querySelector('#confirmCancel').addEventListener('click',()=>closeModal('confirmModal'));const undoBtn=document.querySelector('#undoDelete');if(undoBtn)undoBtn.addEventListener('click',undoDelete);const undoX=document.querySelector('#undoDismiss');if(undoX)undoX.addEventListener('click',clearUndo);document.querySelector('#confirmClose').addEventListener('click',()=>closeModal('confirmModal'));const moreYou=document.querySelector('#personalShowMore');if(moreYou)moreYou.addEventListener('click',()=>showMoreFeed('personal'));const moreCrew=document.querySelector('#crewShowMore');if(moreCrew)moreCrew.addEventListener('click',()=>showMoreFeed('crew'));['identityModal','proxyModal','weekReviewModal','confirmModal','personModal','setupModal'].forEach(id=>{const m=document.querySelector('#'+id);if(m)m.addEventListener('click',event=>closeIfScrim(event,id))});document.querySelector('#todayBounties').addEventListener('click',event=>{const btn=event.target.closest('[data-claim-bounty]');if(btn)claimBounty(btn.dataset.claimBounty)});const weekToggle=document.querySelector('#bountyWeekToggle');if(weekToggle)weekToggle.addEventListener('click',toggleBountyWeek);const claimedTgl=document.querySelector('#claimedToggle');if(claimedTgl)claimedTgl.addEventListener('click',toggleClaimed);document.querySelector('#todayCategories').addEventListener('click',event=>{const chip=event.target.closest('[data-cat]');if(chip)prefillCategory(chip.dataset.cat)});document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.modal.open').forEach(x=>closeModal(x.id))});document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')return;if(challengeToday()!==state.renderedDay)render();if(state.endpoint&&Date.now()-state.lastSyncedAt>300000)loadRemote()});const start=location.hash.slice(1);showTab(['you','record','crew'].includes(start)?start:'you');render();if(state.endpoint)loadRemote();else{if(!participant(state.me))openIdentity(false);maybeShowWeekReview()}}
if(typeof document!=='undefined')init();
